  (tmdb_id, title, genre, duration_min, rating, synopsis, poster_from, poster_to, poster_url, backdrop_url, vote_average, trailer_key, release_date)
values
(1565598, 'Dan Bandung', 'Drama', 120, 'NR', 'Basil, a working-studying Fine Arts student, falls in love with Elma after meeting her at a Persib soccer match. He creates a t-shirt featuring her image that goes viral, leading to their acquaintance and eventual dating. However, their relationship faces opposition from Elma''s father, forcing Basil to fight for his love amidst various obstacles.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/fSK0eQ6toOrjTpRtqB1WoqN50cc.jpg', 'https://image.tmdb.org/t/p/w1280/3W9ipa59TAws4nAbaP0SdksktJG.jpg', 6.2, 'l5GGKpxcCYc', '2026-08-20'),
(1378262, 'Lobang Buaya, 309 Hari Sebelum Tragedi Berdarah', 'Kejahatan', 99, 'NR', 'When a spate of gruesome killings rocks the countryside in East Jakarta, army officer Soegeng is tasked with clearing up rumours about the military’s involvement. Soegeng’s investigation, however, confronts him with the foundations of corruption – a truth too close for comfort.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/eWgVIP4Z3BkgdOSbkO6Sr46ffyt.jpg', 'https://image.tmdb.org/t/p/w1280/mOLtKIvXd1SmobFAaANA1MOuoDk.jpg', 6, 'bxLqGxvjiYQ', '2026-10-01'),
(1420041, 'Memburu Pemangsa', 'Aksi', 115, 'NR', 'Sekelompok jurnalis sedang menginvestigasi kasus pembunuhan anak, namun tiap petunjuk justru membuka teror baru, dan mencari tahu terlalu dalam membuat mereka dalam bahaya yang tak mereka pahami.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/iF8QBPgMvrqv1HEIPH2eIh6Z4eQ.jpg', 'https://image.tmdb.org/t/p/w1280/44fTEcaEtk7PmGFPZUSQEsThGGF.jpg', 5.7, 'PceQZIf1k70', '2026-09-24'),
(1747310, 'Ghosthing', 'Komedi', 100, 'NR', 'A stoic mortician endowed with the ability to perceive the deceased finds his quiet existence upended when the dramatic spirit of a high-profile influencer refuses to depart, forcing him into an unauthorized investigation to prove her sudden demise was the result of homicide.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/rJYpSH06tKXoSArz6vDBIyaPf9Q.jpg', 'https://image.tmdb.org/t/p/w1280/cnwrrEcuDTwV5H21H35fZbHRUPE.jpg', null, 'WoL7tTL-hJQ', '2026-10-15'),
(1541802, 'Operasi Pesta Copet', 'Komedi', 113, 'NR', 'In a desperate act to get quick money, Ijal and friends embark on a high-stakes operation: pickpocketing at Indonesia''s biggest music festival, Pestapora.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/q6jhaPlAnzNFuvPDbDXBDbavIXE.jpg', 'https://image.tmdb.org/t/p/w1280/zj0UjmCotGH7BnMRbKEr5ZxQUZE.jpg', 8, 'OB6e0VrfUyQ', '2026-08-27'),
(1716269, 'Rumah Singgah', 'Drama', 113, 'NR', 'Karla, a talented young runner diagnosed with bone cancer, receives treatment at a halfway house. There, she learns to accept reality through the support of the residents and bu Andin, while together they realize their ultimate dream.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/m3N5NcK4rE7GOaWAuefr0xbncpX.jpg', 'https://image.tmdb.org/t/p/w1280/4WkrOK5DkGO0QIdggzejKoBeDOr.jpg', 7.6, 'B-LKbBHGWa4', '2026-08-27'),
(1450470, 'Perumahan Laddaland', 'Drama', 99, 'NR', 'Demi memberikan kehidupan yang lebih layak bagi istri dan anak-anaknya, Tomy (Andri Mashadi) memberanikan diri mengambil KPR untuk membeli rumah impian. Kebahagiaan itu tak berlangsung lama. Sejak menempati perumahan baru, keluarganya diteror berbagai kejadian tak wajar. Bisikan misterius, penampakan mengerikan, dan rahasia kelam di balik perumahan tersebut mengancam keselamatan mereka.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/nQvMdF0bUEEM0jDzpWMUcaAkGsH.jpg', 'https://image.tmdb.org/t/p/w1280/mY2iDDJxNJkZ3HWJps7N5MzBjWz.jpg', 4, 'yo7X5ouM-Kg', '2026-08-13'),
(1716222, 'Paket Santet', 'Kengerian', 98, 'NR', 'Sebuah paket tiba di depan pintu. Tidak ada nama pengirim. Tidak ada alasan mengapa paket itu ditujukan kepada mereka. Namun, sejak paket itu dibuka, hidup penerimanya langsung berubah jadi mimpi buruk. Satu per satu nyawa menjadi taruhan. Kini, pertanyaannya bukan lagi bagaimana cara menghindari paket tersebut, melainkan bagaimana cara terhindar dari kutukan setelah menerimanya.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/ooeIRaAM9N02d8Z4eXPKE5BlBMM.jpg', 'https://image.tmdb.org/t/p/w1280/wP70ACOajhix1Ko845sBxUT9vkG.jpg', 6, 'iAAtCbIbGfU', '2026-08-27'),
(1567791, 'Munafik: Melawan Iblis', 'Kengerian', 103, 'NR', 'Di perjalanan pulang setelah membantu sebuah keluarga mengusir Iblis di tubuh anak mereka, Adam (Arya Saloka) seorang pengajar agama sekaligus praktisi ruqyah mengalami kecelakaan maut yang membuatnya kehilangan Aini, istrinya. Sejak saat itu ia berhenti melakukan ruqyah dan hidup dalam kesedihan berkepanjangan. Sampai suatu hari, ia diminta Anwar (Dimas Aditya) menyelamatkan Fitri (Acha Septriasa) seorang perawat sekaligus putri dari Mansur (Donny Damara), figur yang dihormati di desa tempat Adam tinggal. Adam yang awalnya menolak menemukan alasan untuk kembali melakukan ruqyah karena mengingat pesan mendiang istrinya. Namun, seiring waktu ia menemukan ada rahasia gelap di balik terror gaib yang menimpa Fitri.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/sXrzWnoA14DWSMUqCEY0o0CTxPg.jpg', 'https://image.tmdb.org/t/p/w1280/9W2ZK1AzTE8WIw10gnzDzVLzXEc.jpg', 6.8, 'gkij9R9EV5o', '2026-09-03'),
(1739312, 'Warga Rusun 609', 'Komedi', 103, 'NR', 'The idiosyncratic tenants of a public housing complex must form a unified front to resist an aggressive municipal demolition plan, all while covertly managing a severe supernatural haunting inside Room 609 by an aggrieved spirit demanding an unfulfilled romantic vow.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/d9k5T523oJjvNBEduSIuBJ6rvpR.jpg', 'https://image.tmdb.org/t/p/w1280/7uQrqaL25mCJXCCSYDBPRHfxGEu.jpg', 5, 'HK3qtX_S0FQ', '2026-10-01'),
(1764235, 'Disonansi', 'Dokumenter', 19, 'NR', 'A documentary about a married couple navigating life amidst financial hardship, social pressure, and family rejection. Through the choices they make, the film explores the disconnect between faith, life, and reality a disconnect that creates dissonance within them and their surrounding environment.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/1iTecPbz6w4OK4X7oS0nH9SRnlR.jpg', 'https://image.tmdb.org/t/p/w1280/3H5HFBkjNrruUt8tZ0Rqynatvug.jpg', null, null, '2026-09-04'),
(1727650, 'Ibadah & Cinta', 'Drama', 116, 'NR', 'A secular young man raised in Australia undergoes a profound spiritual awakening after falling in love with the daughter of a prominent Islamic scholar, only for their matrimonial aspirations to be jeopardized by a pre-arranged betrothal mandated by her traditionalist family.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/cQlIFMvnAAUH9MZ7l1UkSD13ddB.jpg', 'https://image.tmdb.org/t/p/w1280/v9pNRRWO5gZ1ybKxmKVeL7yTgSD.jpg', 7, '_k-qM7bnIbg', '2026-09-24'),
(1589665, 'Kuasa Gelap: Perjanjian Darah', 'Kengerian', 117, 'NR', 'Following a catastrophic, failed ritual in a remote Indonesian province, two Catholic exorcists are deployed to confront a devastatingly powerful ancient entity unleashed by an ancestral pact for illicit wealth.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/pnr5cn7TJlGw6yUMgbCtDkGRLuQ.jpg', 'https://image.tmdb.org/t/p/w1280/yPeEsPDAsTrYpBNEwaO4xziacuI.jpg', 6.7, 'DKaO7xm7tpo', '2026-10-08'),
(1757007, 'Kuru'' Sumange''', 'Drama', 100, 'NR', 'In a small town in the Bugis region, seven children from diverse backgrounds are brought together for a Regional Children''s Festival. Aisyah, a lonely girl, meets fellow participants who are each grappling with their own personal struggles. The judges group them together to stage a top-notch performance, and a variety of conflicts arise, challenging them to keep the show going in the name of friendship.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/4TP3GC9HpBJKE6ST1W3ZM5M2m3.jpg', null, null, null, '2026-08-30'),
(1601704, 'Hasut', 'Kengerian', 96, 'NR', 'In the wake of their parents'' tragic decease, a young woman orchestrates a remote wilderness expedition to rehabilitate her estranged sister, only for the group to be terrorized by manipulative supernatural entities exploiting their communication devices.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/wNv9rYd0Nqeq5vWPwyicognSER3.jpg', 'https://image.tmdb.org/t/p/w1280/sRpgypBSBlEqT3PEUIFoouuSUwX.jpg', 6, '6FDtvY6r9uo', '2026-10-08'),
(1280076, 'Empat Musim Pertiwi', 'Drama', 137, 'NR', 'Pertiwi returns to her hometown after spending two decades in prison to rebuild her life. There, she finds power in things that have been abandoned: discarded electronic devices that mysteriously light up and a community of outcasts living on the fringes of society. But coming home also means confronting the four men who sent her to prison and now rule the village. Together with the outcasts, Pertiwi begins to uncover the darkness that still haunts the place - and the past she thought she had left behind.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/gjDK2E0FNwCxy3B915ODQZfy4QD.jpg', 'https://image.tmdb.org/t/p/w1280/7GtW8tgNMc8iL6nvzkY2vAwNvQs.jpg', 8.3, 'SV4PIdI9JL0', '2026-09-22'),
(1601709, 'Bapakmu Kiper', 'Komedi', 90, 'NR', 'The story follows an 18-year-old named Ronaldhino Sujatmiko—known as Dino—who harbors anger toward his father, Warto. Warto is a former local soccer star and soccer gambler whom Dino believes is responsible for his mother’s death. Dino’s chance to leave his village comes through the Tarkam Super Cup, a soccer talent search tournament. The conflict comes to a head when Dino’s main team is taken over by another party just before the final. This situation forces his father, Warto, to step in and form a new team made up of veteran players, despite all the limitations they face.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/e91DcxPpBfjAuVf67rP8zVFEjBi.jpg', 'https://image.tmdb.org/t/p/w1280/6dporxDetmS1eYrmIbpZfLdX81D.jpg', 5, 'zDv6_dfI7F8', '2026-09-03'),
(1740545, 'Conjurig', 'Drama', 95, 'NR', 'Following a sudden job loss and the dissolution of his romantic relationship in the capital, a dejected young man retreats to his hometown of Bandung, masking his psychological vulnerabilities by donning a traditional ghost costume within a local street-performing subculture.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/hWhVOc0ErQiyHH5q4AskPjaYeXT.jpg', 'https://image.tmdb.org/t/p/w1280/5m1bJ4pn69DgHQv9oUzoOFpht5L.jpg', null, 'j3CsY68ThoY', '2026-10-01'),
(1735309, 'Istimewa', 'Drama', 119, 'NR', 'Five disabled children embark on a desperate search for their runaway foster father, only to find themselves thrust into the public eye.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/eGqZmMRqVDdtgobGENgUYGAgiOu.jpg', 'https://image.tmdb.org/t/p/w1280/nKx4acOCV1U2EXJUMbIL00xbMlE.jpg', 6.5, 'Fjg4whNQH-Y', '2026-09-17'),
(1699756, 'Ayah, Aku Mau Cerita....', 'Kejahatan', 166, 'NR', 'When his family stares down the barrel of criminal charges, a commoner channels his street smarts and knowledge of action films to tie the long arm of the law into an investigative Gordian knot.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/1nHqIu8RAOv16yAWbVSL0XTsk3i.jpg', 'https://image.tmdb.org/t/p/w1280/oj93gx6nEqcmU8sFDr5c43bA0Jl.jpg', 6.5, '9nI65nJULvQ', '2026-08-20'),
(1469930, 'Tumbal Proyek', 'Kengerian', 106, 'NR', 'While investigating their father’s death inside a major bridge construction company, Yuda and his family attempt to prove that the frequent, deadly workplace accidents are actually human sacrifices.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/wdOa8jWX8u1YNSlWyRvoNCc9y7S.jpg', 'https://image.tmdb.org/t/p/w1280/k3Nc57fdRkzleHjodta45mGJV2C.jpg', 3.9, 'StEBQjJcubs', '2026-05-13'),
(1421155, 'Ikatan Darah', 'Aksi', 119, 'NR', 'A former martial arts athlete must face a network of loan sharks to save her younger brother, who is trapped in online gambling debt and risking their family’s safety.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/lF9amilOGIudUIq6NgDnz2YrPPa.jpg', 'https://image.tmdb.org/t/p/w1280/j5L5e211nYRd8DiLNDXbeGUsx7D.jpg', 6.5, 'Qq2Plb_X0gc', '2026-04-30'),
(1783923, 'Bittersweet Seventeen', 'Drama', 6, 'NR', 'Setelah merusak mobil mainan saudara kembarnya, Vina (17) menjual gaun ulang tahunnya dan membeli mainan baru untuk membujuk saudaranya yang marah padanya.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/7POrJ3PJho1zVaMs2Fqhb1Ri0kS.jpg', 'https://image.tmdb.org/t/p/w1280/83hoAV2WNiVzPDjPuJZzH53s8b2.jpg', 10, null, '2026-07-07'),
(1786667, 'Home, Almost', 'Aksi', 19, 'NR', 'A story about an MMA fighter who finds himself in another fight on the way home. — with his father and younger brother by his side, finding the true meaning of family along the way.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/xGczzc3uHAp4ELWxKnhvplrzyXo.jpg', null, null, 'wgm28pN2pww', '2026-10-15'),
(1590613, 'Cerita Lila', 'Kengerian', 106, 'NR', 'Lila, arwah seorang gadis kecil yang masih terikat pada masa lalunya, terus mencari saudari kembarnya yang hilang, Lili. Kehidupannya berubah saat Nia dan ibunya, Tari, pindah ke rumah tempat Lila berada. Persahabatan yang terjalin antara Lila dan Nia membawa mereka pada pencarian yang perlahan membuka rahasia kelam yang lama terkubur. Ketika kehadiran sosok Rahma mulai mengancam keselamatan mereka, Nia meminta bantuan Sara Wijayanto dan Wisnu untuk mengungkap kebenaran di balik tragedi masa lalu.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/80CcJdrV3ewqPawFMAFGIrldgR5.jpg', 'https://image.tmdb.org/t/p/w1280/9rZVlvA5Nk3SA4GJk1ySUbZLtTg.jpg', 5, '_S9ummr0mjg', '2026-06-18'),
(1616674, 'Aku Sebelum Aku', 'Drama', 127, 'NR', 'A young student battling pressure, panic and a demanding father uses a class project to discover that truth — not trophies — might finally set him free.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/xmwPr0YOFS6vC3aydnE85gxp36t.jpg', 'https://image.tmdb.org/t/p/w1280/1QiFfqaAhZi4HMlJNMvJVXOovc6.jpg', 6.7, null, '2026-07-11'),
(1707875, 'Sang Penjaga', 'Drama', 11, 'NR', 'Di keriuhan pasar malam, Ardo mengikuti Ladya mencari seuntai kalung. Di sana, mereka merajut ruang aman yang asing, sebelum kenyataan menarik paksa Ardo pulang dan membiarkan Ladya memudar menjadi cahaya.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/wpMMlhMBn4FgeCKVvrA2tKy5yUB.jpg', null, null, null, '2026-06-06'),
(1263904, 'Monster Pabrik Rambut', 'Kengerian', 96, 'NR', 'PUTRI (Rachel Amanda) kehilangan ibunya, yang mati setelah beberapa hari tak tidur karena bekerja siang dan malam. Menurut MARYATI (Didik Nini Thowok), pemilik pabrik, ibunya mati bunuh diri. Awalnya ia percaya, tapi IDA (Lutesha), adiknya, mengatakan bahwa ibu mereka mati karena kesurupan. Untuk membuktikan omongannya, Ida memutuskan untuk lembur, tak tidur berhari-hari, demi melihat sendiri sosok hitam yang merebut tubuh ibunya. BONA (Iqbaal Ramadhan), adik bungsu mereka, memiliki kemampuan spesial. Ia mampu meregenerasi bagian tubuhnya. Sosok hitam berhasil menyandera Bona. Mampukah Putri dan Ida menyelamatkan Bona?', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/fiapXpPfhW3Uqjj0jMIVtaAdGRc.jpg', 'https://image.tmdb.org/t/p/w1280/m7pUxa1AaXjuvpFJsb4hvB25Lv.jpg', 7.2, 'onMcP76Nam8', '2026-06-04'),
(1590909, 'Ibuku', 'Drama', 95, 'NR', 'A destitute widow and former traditional dancer defies social ostracization to embark on a desperate international journey, seeking a final reconciliation with her estranged daughter who faces execution abroad for the murder of an abusive employer.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/zYwxtzF9wIAPybLfU4s7sADX3ZG.jpg', 'https://image.tmdb.org/t/p/w1280/4HnXizTOzGJYc1FaHslow31dzZu.jpg', null, 'ItgV0HrDh9Q', '2026-10-08'),
(1589713, 'Badut Gendong', 'Aksi', 101, 'NR', 'Darso, a clown busker, lost his wife and unborn child to thug violence. In grief, he brought his wife''s body back to his village. However, the village is in chaos due to a conflict with an evil developer and a curse ritual that summons dark forces. Darso is also caught up in the evil forces connected to the person he loves most.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/kIAltyOVZFIRFFFgBUBABb0HyF7.jpg', 'https://image.tmdb.org/t/p/w1280/aVnrli2pknnbAeGhsjhLBWc5yCL.jpg', 8, 'yPaqYzR_ocI', '2026-05-27'),
(1771501, 'Adagium', 'Aksi', 14, 'NR', 'A hired hitman is paid to assassinate a corrupt politician, but after witnessing the failure of the justice system, he begins taking the law into his own hands.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/a5HYQ5AVDBXKXrMLBM7lQgX2p17.jpg', 'https://image.tmdb.org/t/p/w1280/b9XoyipvU4NJsuCzFsHTScESqPQ.jpg', null, null, '2026-09-16'),
(1423191, 'Resident Evil', 'Kengerian', 95, 'NR', 'Medical courier Bryan unwittingly finds himself fighting for survival as one fateful, horrifying night collapses around him in chaos.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/i7UyjfPio0VFHB9rBUZSFyhOoM8.jpg', 'https://image.tmdb.org/t/p/w1280/3icyRAqgakNcQn6aDVz9libFmBA.jpg', 7.3, 'mNd1gb19A-c', '2026-09-16'),
(1101412, 'Fall 2: Deadpoint', 'Cerita Seru', 98, 'NR', 'On a perilous climb across Thailand''s Mount Kwan, two climbers become trapped thousands of feet above the ground, where vertigo-inducing heights, sheer exposure, and impossible odds turn every moment into a fight for survival.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/fgSm5ylwiXbIHn8UbUXDjk9RRu4.jpg', 'https://image.tmdb.org/t/p/w1280/yBDxqDB29kpH9VojTytjGWBgmdJ.jpg', 7.3, 'Krs0VDIjhmE', '2026-09-01'),
(1377237, 'Runner', 'Aksi', 97, 'NR', 'A former soldier is thrown into a brutal race against time when a critical medical delivery makes him and his unlikely partner the targets of a ruthless cartel. As the mission spirals into a deadly manhunt, every detour, delay, and bullet pushes them closer to failure. With betrayal closing in from every side, they must survive the chase and deliver their cargo to save the life of a little girl.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/yBKMAIj7clP42UkFejhGDBBoTpb.jpg', 'https://image.tmdb.org/t/p/w1280/npXZNWjOEYrqdMDPQ11SGBrXqAG.jpg', 8.3, 'B6Z9MM1LhEA', '2026-09-07'),
(1400837, 'Other Mommy', 'Kengerian', 93, 'NR', 'Young Bela forms a relationship with a sinister entity in her home that looks uncannily like her own mother, drawing her into a terrifying and increasingly dark world.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/fGRNCssTRrhYZxNzykGGCoMsAVq.jpg', 'https://image.tmdb.org/t/p/w1280/ncm7djsVTHQQMX2HEbEVxMUFchG.jpg', 6, '-mnTITqqiT0', '2026-10-07'),
(1058424, '호프', 'Cerita Fiksi', 157, 'NR', 'In the remote South Korean village of Hope Harbor, police chief Bum-seok and officer Sung-ae are called to investigate a mysterious creature wreaking havoc on the community. But all is not as it seems, and perceptions can be misleading. What begins as ignorance plants the seed of disaster, escalating through human conflict into a tragedy of cosmic proportions.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/ptqlN6mDIAqJjVA86J5eOoG82zc.jpg', 'https://image.tmdb.org/t/p/w1280/xBcKnWJHodUpvzUVIWTuNMnvEwl.jpg', 7.1, 'OFaJzL83y0Q', '2026-07-15'),
(1302904, 'Practical Magic 2', 'Percintaan', 130, 'NR', 'The Owens sisters must confront the dark curse that threatens to unravel their family once and for all.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/ogwQOLbCfncjvBhFb5l0OmQH8KC.jpg', 'https://image.tmdb.org/t/p/w1280/oIglj0Jy9duG4LnrRUpH8n001Pk.jpg', 6.3, 'Ho10_4IX1jE', '2026-09-09'),
(1248832, 'Digger', 'Komedi', 129, 'NR', 'The most powerful man in the world embarks on a frantic mission to prove he is humanity''s savior before the disaster he''s unleashed destroys everything.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/1ATXKrIPJyKNwnJ6lcG088Sa6zi.jpg', 'https://image.tmdb.org/t/p/w1280/b7t3r39Oll5qPxBKzLZ8eHMBD7l.jpg', 7.5, 'job8V254NAE', '2026-09-28'),
(299534, 'Avengers: Endgame', 'Petualangan', 181, 'NR', 'Terdampar di luar angkasa tanpa persediaan makanan dan minuman, Tony Stark berusaha mengirim pesan untuk Pepper Potts dimana persediaan oksigen mulai menipis. Sementara itu para Avengers yang tersisa harus menemukan cara untuk mengembalikan 50% mahluk di seluruh dunia yang telah dilenyapkan oleh Thanos.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/bR8ISy1O9XQxqiy0fQFw2BX72RQ.jpg', 'https://image.tmdb.org/t/p/w1280/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg', 8.2, 'L2NAh3CIdig', '2019-04-24'),
(1283515, 'Verity', 'Misteri', 114, 'NR', 'Lowen Ashleigh, hired to ghostwrite for best-selling author Verity Crawford, uncovers Verity''s autobiographical notes, and becomes involved in what may prove to be a lethal conspiracy.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/zPHfsaiMZT1HNz1ZS55iyLKZkFG.jpg', 'https://image.tmdb.org/t/p/w1280/3BoHXmGAfC2qO4wnCpMYV0BzpHD.jpg', 6.3, 'xdPMKhjMSFs', '2026-09-30'),
(1263337, 'Heart of the Beast', 'Petualangan', 101, 'NR', 'After a harrowing plane crash, Special Forces officer James Belmont and his combat dog, Odin, find themselves stranded deep in the Alaskan wilderness. Together, they are forced into a brutal fight for survival against the elements.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/1ApfSA8JTqeha3GTFEY8syV4auq.jpg', 'https://image.tmdb.org/t/p/w1280/bicMU6xVD5deVyKP2azpyx7xkmH.jpg', 7.4, 'UkMuGKqAux4', '2026-09-19'),
(1281331, 'The Social Reckoning', 'Drama', 113, 'NR', 'Frances Haugen, a young Facebook engineer, enlists the help of Jeff Horwitz, a Wall Street Journal reporter, to go on a dangerous journey that ends up blowing the whistle on the social network''s most guarded secrets.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/7jK6NuxVg1XuEV7UdNa6KO03IgZ.jpg', 'https://image.tmdb.org/t/p/w1280/wXTaGcqX3jvdXSKCJAkl5jZyrKp.jpg', 7, 'R8ANzYpaZaY', '2026-10-07'),
(1153576, 'Street Fighter', 'Aksi', 120, 'NR', 'In 1993, estranged Street Fighters Ryu and Ken Masters are thrown back into combat when the mysterious Chun-Li recruits them for the next World Warrior Tournament: a brutal clash of fists, fate, and fury. But behind this battle royale lies a deadly conspiracy that forces them to face off against each other and the demons of their past. And if they don''t, it''s GAME OVER!', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/dJPT2Uf12X6aFg8i5N67NTpIZ9t.jpg', 'https://image.tmdb.org/t/p/w1280/zDE9hd1SG9695YncbZGjSf7Z9Jk.jpg', 6.8, 'U6sbm1OaJb8', '2026-10-13'),
(1465063, 'Forgotten Island', 'Animasi', 109, 'NR', 'While celebrating their last night together, high school graduates and best friends Jo and Raissa stumble upon a mysterious portal that transports them to the fantastical island of Nakali. When they discover that the memories of their entire friendship are the price for returning home, Jo and Raissa must race to find a way to leave the island before they forget each other forever.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/myd1K3gefdNAWFsGNRDdMeiK9Qg.jpg', 'https://image.tmdb.org/t/p/w1280/cNICUho5uiAGkfCAQq1ihyaMla4.jpg', 8.1, 'PhgY8cOJiQA', '2026-09-10'),
(1594914, 'Lucky Strike', 'Aksi', 102, 'NR', 'A wounded American soldier fights to survive behind enemy lines during WWII''s Battle of the Bulge against the Germans, relying on his instinct, spy craft and a hand-radio to evade capture and find his way back to his unit.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/kzRAd7mj39ZY3FGNrDdZjqx56tn.jpg', 'https://image.tmdb.org/t/p/w1280/uujYvxE9s6KY4SbBZ0ZFN3oBJhW.jpg', 6.6, 'vtEnjikCXyA', '2026-06-26'),
(1400499, '近畿地方のある場所について', 'Kengerian', 103, 'NR', 'After an editor of an occult magazine suddenly vanishes, his friend Chihiro and his co-worker Yusei set out to discover the reason behind his disappearance.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/fhKkr22UpULWNemcgCjppTkHXgf.jpg', 'https://image.tmdb.org/t/p/w1280/e0vwcf5R1yU2Uz2mTO4KbCxL5tT.jpg', 6.3, null, '2025-08-08'),
(1447853, 'Oasis: Don''t Look Back in Anger', 'Dokumenter', 123, 'NR', 'Experience the meteoric rise of Oasis through rare footage and untold stories as the band reunites for Oasis Live ''25, chronicling their journey from Manchester streets to global rock stardom.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/5XoHhKZ1IROW6f5UlRpADHnTL2l.jpg', 'https://image.tmdb.org/t/p/w1280/7Ud7QIJo21odjCaev6V4md9sK16.jpg', 7.5, 'X9sIYLtgc_s', '2026-09-09'),
(1400940, 'Clayface', 'Kengerian', 108, 'NR', 'Matt Hagen''s meteoric rise from Gotham street kid to Hollywood leading man is tragically cut short when a local crime boss''s actions leave him horribly disfigured. Abandoned by his team and with nothing left, Matt seeks out a cutting edge treatment that miraculously returns him to his former self… but also unexpectedly affects his grip on reality, spiraling him down a destructive path of all-consuming revenge.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/5jCpQnWPikggmQZoDp1eAi6BI6w.jpg', 'https://image.tmdb.org/t/p/w1280/kVtOcoUJ68chBD2tmERkdWz7lK5.jpg', 8.3, 'KCR-rz0YfD4', '2026-10-21'),
(1269325, 'दृश्यम: आखिरी हिस्सा', 'Cerita Seru', 148, 'NR', 'Years after outsmarting the police, Vijay Salgaonkar''s past resurfaces when a new evidence threatens to expose his secret. As the investigation reopens, he must outwit the system once again to save his family.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/7T62GSduOWDMB0gGDBs9pmtLTSB.jpg', 'https://image.tmdb.org/t/p/w1280/nq73eRdEooripf3k0XHLtX14zyC.jpg', 7.7, 'MFQFxsDWbA8', '2026-10-02'),
(1234139, 'ஜெயிலர் 2', 'Aksi', 163, 'NR', 'When a dangerous syndicate expands its reach to threaten his family''s peace, retired jailer Tiger Muthuvel Pandian goes undercover as a driver. Operating from the shadows, he takes on ruthless new enemies to protect his home.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/upwdEyhhYZ7pT2hD535fr2MGfpx.jpg', 'https://image.tmdb.org/t/p/w1280/m0ks2o59mOAz6WdCybJ5FAUNTOU.jpg', null, null, '2026-10-14'),
(1755291, 'NAZA', 'Dokumenter', 77, 'NR', 'Filmed at night from Tel Aviv rooftops, this investigative documentary examines the civilian casualties of Israel''s military operations in Gaza and the systems behind targeted killings of Palestinians.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/bYfN1EKVyj2O7KXwuWDDCc47B5T.jpg', 'https://image.tmdb.org/t/p/w1280/7EzH0dlEN9OZWWBXBWwT5PbMNUz.jpg', 8.2, '40KW6knYMo4', '2026-09-25'),
(1148365, 'Matchbox the Movie', 'Aksi', 127, 'NR', 'Ketika sekelompok mantan teman masa kecil bertemu kembali, reuni mereka menjadi kacau saat tak sengaja menemukan konspirasi internasional yang berbahaya dan kini mereka harus menyelamatkan dunia.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/lFKA4GMz36dImEy3DQPdPF7G4V9.jpg', 'https://image.tmdb.org/t/p/w1280/y6RIuwuxLG3Nsb37KUj5yatnTIp.jpg', 7.9, '7xfqITrMDcI', '2026-10-05'),
(1368337, 'The Odyssey', 'Petualangan', 173, 'NR', 'Odysseus, raja legendaris Yunani dari Ithaca, memulai perjalanan panjang dan berbahaya untuk pulang setelah Perang Troya, yang mengisahkan perjumpaannya dengan makhluk-makhluk mitologis seperti Cyclops Polyphemus, para Siren, dan penyihir-dewi Circe.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg', 'https://image.tmdb.org/t/p/w1280/twiVn9oFXOVR0uoYgawyEBlnFu8.jpg', 8, 'AyIZ9tiiN8I', '2026-07-15'),
(1236045, 'Animals', 'Cerita Seru', 109, 'NR', 'Saat putra mereka diculik, seorang kandidat wali kota LA dan istrinya kalang kabut mengumpulkan tebusan sambil membuat keputusan yang bisa menghancurkan hidup mereka.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/iISM36voS1E8gX9BM0DVK0kgi3E.jpg', 'https://image.tmdb.org/t/p/w1280/tzoarEu7TsG959upiELyYPm5kO9.jpg', 7.3, 'ZkN2M4ODdys', '2026-10-09'),
(1228834, 'The Fix', 'Aksi', 142, 'NR', 'Disillusioned by the end of the war in Afghanistan, a group of disgraced, war-torn ex-CIA operatives set out to Tehran to take down a life-changing score.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/jlP8XDjZN89GrpM3je5Uf8Grqx8.jpg', 'https://image.tmdb.org/t/p/w1280/yT8EkAvEkJDFeAxK7s7HlIPELRT.jpg', 6.8, 'l5Luvr9TRRc', '2026-09-10'),
(1751701, 'After Impact', 'Cerita Fiksi', 95, 'NR', 'After losing his father, Ethan Nichols inherits one of the largest greenhouses in the country, just as the world faces a devastating threat from an approaching asteroid. As society begins to unravel, Ethan grapples with personal betrayal, overwhelming loneliness, and the growing fear that survival may come at the cost of his humanity. Seeking refuge in his family’s bunker, Ethan endures the harsh aftermath of the impact, wrestling with physical injury and emotional despair. When a faint voice crackles over his radio, Ethan discovers he''s not as alone as he believed.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/yzDuAQCY2n6zzOlBkn6JzhLhY3k.jpg', 'https://image.tmdb.org/t/p/w1280/k22XyPbce7zvzzf5OnT4uaY8ZD1.jpg', 5.8, 'Af8D6sRDyxo', '2026-09-15'),
(1204680, 'Coyote vs. Acme', 'Komedi', 103, 'NR', 'After Acme products fail him one too many times in his dogged pursuit of the Roadrunner, Wile E. Coyote decides to hire a billboard lawyer to sue the Acme Corporation.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/kYDCl2y0VPvhT5eYWbMRInPoB03.jpg', 'https://image.tmdb.org/t/p/w1280/viZqGq9TNvQ5uXSD4ahg2RpRONT.jpg', 7.5, 'kMsiD1Nky5I', '2026-08-20'),
(1232569, 'Pinocchio: Unstrung', 'Kengerian', 82, 'NR', 'Influenced by a sinister Cricket and created by Geppetto, Pinocchio launches a violent crusade to carve himself into a real boy like his brother James, one piece at a time.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/hJNdizFlxOW89edX3Rzr6OliSFI.jpg', 'https://image.tmdb.org/t/p/w1280/7RsPdXLDNugDIlwXPVeeprNfMx.jpg', 6.5, 'Y4lZewE6JMI', '2026-07-22'),
(1284046, 'Onslaught', 'Aksi', 92, 'NR', 'When a rogue squad of genetically engineered super soldiers break loose in the desert, a badass Army sniper must unleash hell to protect her young daughter.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/cOGtvhc6Ij9KvzM6jZsfQyg0B0O.jpg', 'https://image.tmdb.org/t/p/w1280/clePZhqOSzNyjfuFBpOrziLEFzb.jpg', 5.8, 'AMLCbpM1fRQ', '2026-09-02'),
(1339713, 'Obsession', 'Kengerian', 109, 'NR', 'Setelah menghancurkan "One Wish Willow" yang misterius untuk memenangkan hati gebetannya, seorang romantis yang putus asa menemukan dirinya mendapatkan apa yang dia minta tetapi segera menemukan bahwa beberapa keinginan datang dengan harga yang gelap dan menyeramkan.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', 'https://image.tmdb.org/t/p/w1280/5lTZyuBTNOfawsfPT8Q0cIg6qAF.jpg', 8.2, 'gMC8kkwbIQQ', '2026-05-13'),
(1288445, 'Mutiny', 'Aksi', 96, 'NR', 'After witnessing his billionaire boss'' murder and being framed for the crime, Cole Reed boards a cargo ship on a one-man crusade to avenge his boss'' death only to discover an international conspiracy.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/pu2VxGlpGwffOx292w18b1tv96j.jpg', 'https://image.tmdb.org/t/p/w1280/e2QAGrEmbpmZpMymDRkDisJkvg9.jpg', 7.6, '2Iqvbe98Gb4', '2026-08-19'),
(1389172, 'रिपोर्टिंग लाइव', 'Kejahatan', 116, 'NR', 'A young reporter and her reluctant cameraman chase a story, only to get entangled in an illegal sand-mining racket run by a ruthless syndicate.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/72ETmrsQGk8guVo1GV8Sf7EygOe.jpg', 'https://image.tmdb.org/t/p/w1280/faJB8DXU0LXwq5ebMLj5drz8S4N.jpg', 8.1, 'GgGNG9XEJds', '2026-10-09'),
(1280300, 'The Whistler', 'Misteri', 97, 'NR', 'Reeling from their daughter''s loss, Nicole and Sebastian come into possession of a secluded Venezuelan farm, unaware of the dark forces they''re about to face.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/sX8tqkFR1aqZaLQ4Jgb8jEMB4RN.jpg', 'https://image.tmdb.org/t/p/w1280/qz8m7DGpuhc4RJmCbHsdueQKkTg.jpg', 5, '8PNnVN8NSHk', '2026-09-24'),
(1514026, 'Buddy', 'Kengerian', 95, 'NR', 'A magical, singing orange unicorn holds his cast hostage in a surreal TV-show dimension, as he becomes more and more demented.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/1BdZbNvl1SfrrX8J9X5tQzN6Ivu.jpg', 'https://image.tmdb.org/t/p/w1280/kghxBvN7f3vUt377yjO4ygbefYN.jpg', 7.4, null, '2026-08-27'),
(1742441, 'V/H/S/Mixtape', 'Kengerian', 98, 'NR', 'V/H/S/MIXTAPE cranks the volume on horror with a blood-soaked collection of cursed music videos, terrifying performances, and found footage. Press play. Pray it stops.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/uS8yoiA6NfsuYeOTbVfpem8Ib9.jpg', 'https://image.tmdb.org/t/p/w1280/mpB4pgtUcc7rCLxvlknzCbAQQEE.jpg', 4.4, 'GrIouRKyPDw', '2026-10-09')
